_PHRASE_RE = re.compile("|".join(re.escape(k) for k in PHRASES))


def fold(text: str) -> str:
    """逐字繁→簡，長度不變。"""
    return text.translate(_TABLE) if text else text


@lru_cache(maxsize=4096)
def unify(text: str) -> str:
    """用於比較的正規化：逐字繁→簡，再把台灣慣用詞換成大陸慣用詞。"""
    folded = fold(text or "")
    return _PHRASE_RE.sub(lambda m: PHRASES[m.group(0)], folded) if PHRASES else folded


# ---------------- 網頁文字的書寫系統偵測 ----------------
_SIMPLIFIED_ONLY = frozenset(_SC)
_TRADITIONAL_ONLY = frozenset(_T) - frozenset(_SC)


def detect_script(text: str) -> str:
    """'simplified' / 'traditional' / 'unknown'：數一數只屬於某一邊的字。"""
    simp = sum(1 for c in text if c in _SIMPLIFIED_ONLY)
    trad = sum(1 for c in text if c in _TRADITIONAL_ONLY)
    if simp >= 3 and simp > trad * 2:
        return "simplified"
    if trad >= 3 and trad > simp * 2:
        return "traditional"
    return "unknown"


def variants(text: str) -> list[str]:
    """同一段文字可能的寫法（原文、逐字簡體、大陸用語），用於在網頁上找字。"""
    out = []
    for v in (text, fold(text), unify(text)):
        if v and v not in out:
            out.append(v)
    return out


# ---------------- 呈現：簡→繁 ----------------
_SEP = "\u0001"
_converter = None


def _opencc():
    global _converter
    if _converter is None:
        try:
            import opencc

            _converter = opencc.OpenCC("s2tw")
        except Exception:  # 依賴缺失時退化為原文，而不是讓整個執行失敗
            _converter = False
    return _converter


def to_trad(text: str) -> str:
    """簡→繁（只轉字形，不改用詞）。已經是繁體或沒有中文的文字原樣返回。"""
    if not text or not any(c in _SIMPLIFIED_ONLY for c in text):
        return text
    conv = _opencc()
    return conv.convert(text) if conv else text


def to_trad_many(texts: list[str]) -> list[str]:
    """批次轉換（一次呼叫 OpenCC），用於頁面快照裡的上百個元素標籤。"""
    todo = [i for i, t in enumerate(texts) if t and any(c in _SIMPLIFIED_ONLY for c in t)]
    conv = _opencc() if todo else None
    if not todo or not conv:
        return list(texts)
    converted = conv.convert(_SEP.join(texts[i] for i in todo)).split(_SEP)
    out = list(texts)
    if len(converted) == len(todo):
        for i, t in zip(todo, converted):
            out[i] = t
    else:  # 分隔符號被吃掉（理論上不會發生）時逐一轉換
        for i in todo:
            out[i] = conv.convert(texts[i])
    return out


def to_trad_deep(value, skip_keys: frozenset[str] = frozenset()):
    """遞迴轉換 dict / list 裡的所有字串（黑匣子事件使用）；skip_keys 內的欄位保留原樣（如網址）。"""
    if isinstance(value, str):
        return to_trad(value)
    if isinstance(value, list):
        return [to_trad_deep(v, skip_keys) for v in value]
    if isinstance(value, tuple):
        return tuple(to_trad_deep(v, skip_keys) for v in value)
    if isinstance(value, dict):
        return {k: (v if k in skip_keys else to_trad_deep(v, skip_keys)) for k, v in value.items()}
    return value
